prologue:
/* Bytes come up more often than serving, so the size helper carries the rest */
static MOD_UNUSED int files_size(const char* path) {
    return API->files != 0 ? API->files->Read(SELF, path, 0, 0) : 0;
}

static MOD_UNUSED int files_served_count(void) {
    return API->files != 0 ? API->files->ServedCount(SELF) : 0;
}

/* The caller frees it; a trailing zero is added because game files are read as text */
static MOD_UNUSED char* files_text(const char* path) {
    char* text;
    const int size = files_size(path);
    if (size <= 0) return 0;
    text = (char*)malloc((size_t)size + 1);
    if (text == 0) return 0;
    if (API->files->Read(SELF, path, text, size) != size) {
        free(text);
        return 0;
    }
    text[size] = 0;
    return text;
}

static MOD_UNUSED int files_contains(const char* path, const char* what) {
    char* text = files_text(path);
    int found;
    if (text == 0) return 0;
    found = strstr(text, what) != 0;
    free(text);
    return found;
}

static MOD_UNUSED const char* files_served_at(int index) {
    const char* name = API->files != 0 ? API->files->ServedAt(SELF, index) : 0;
    return name != 0 ? name : "";
}

static MOD_UNUSED int files_is_served(const char* path) {
    const int count = files_served_count();
    int at;
    for (at = 0; at < count; ++at) {
        const char* name = API->files->ServedAt(SELF, at);
        if (name != 0 && strcmp(name, path) == 0) return 1;
    }
    return 0;
}

static MOD_UNUSED void files_serve_text(const char* path, const char* text) {
    if (API->files != 0) API->files->Serve(SELF, path, text, (int)strlen(text));
}

static MOD_UNUSED void files_clear(const char* path) {
    if (API->files != 0) API->files->Clear(SELF, path);
}

/* The source goes through Read, so it may itself be a file another mod answers for */
static MOD_UNUSED void files_serve_copy(const char* path, const char* from) {
    void* bytes;
    const int size = files_size(from);
    if (API->files == 0 || size <= 0) return;
    bytes = malloc((size_t)size);
    if (bytes == 0) return;
    if (API->files->Read(SELF, from, bytes, size) == size)
        API->files->Serve(SELF, path, bytes, size);
    free(bytes);
}

static MOD_UNUSED void files_append(const char* path, const char* text) {
    char* was = files_text(path);
    const size_t head = was != 0 ? strlen(was) : 0;
    const size_t tail = strlen(text);
    char* joined = (char*)malloc(head + tail + 1);
    if (joined != 0) {
        if (head != 0) memcpy(joined, was, head);
        memcpy(joined + head, text, tail + 1);
        if (API->files != 0) API->files->Serve(SELF, path, joined, (int)(head + tail));
        free(joined);
    }
    free(was);
}

/* Every occurrence, because a script usually repeats the line being changed */
static MOD_UNUSED void files_replace(const char* path, const char* what, const char* with) {
    char* text = files_text(path);
    const size_t oldLen = strlen(what);
    const size_t newLen = strlen(with);
    const char* at;
    char* out;
    size_t grown, count = 0;

    if (text == 0 || oldLen == 0) {
        free(text);
        return;
    }
    for (at = text; (at = strstr(at, what)) != 0; at += oldLen) ++count;
    if (count == 0) {
        free(text);
        return;
    }

    grown = strlen(text) + count * newLen - count * oldLen;
    out = (char*)malloc(grown + 1);
    if (out != 0) {
        char* write = out;
        const char* read = text;
        while ((at = strstr(read, what)) != 0) {
            memcpy(write, read, (size_t)(at - read));
            write += at - read;
            memcpy(write, with, newLen);
            write += newLen;
            read = at + oldLen;
        }
        strcpy(write, read);
        if (API->files != 0) API->files->Serve(SELF, path, out, (int)grown);
        free(out);
    }
    free(text);
}

static MOD_UNUSED void files_clear_all(void) {
    if (API->files == 0) return;
    while (API->files->ServedCount(SELF) > 0) {
        const char* name = API->files->ServedAt(SELF, 0);
        if (name == 0 || API->files->Clear(SELF, name) == 0) break;
    }
}
